(()=>{
 const get=id=>document.getElementById(id),node=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n};
 const figures=[
 ['Information loss by stage','Extraction, feedback and final synthesis. Omissions and distortions are self-coded against the authored source; there is no independent semantic evaluator.'],
 ['Fidelity under compression','250/500/1,000-word caps and 8/32/64-record inputs. All four claims fit the shortest cap; repeated-record panels test volume, not new expert diversity. Actual output lengths are shown.'],
 ['Disagreement and uncertainty','Saved versus reported proportions, status confusion, individual entropy versus between-person dispersion, and a probability-calibration view. Counts are computed; probabilities are an authored supplement.'],
 ['Consequential minority evidence','Supported, unsupported and absent warnings, varying one, four or eight mentions among 32 records. Regret is an explicit-loss-rule sanity check, not an independent reader test.'],
 ['Robustness and mechanism','Reviewed perturbations, information-deletion controls and recorded OpenRouter cost versus fidelity. Equivalent-input cases reuse reviewed text. Independent model replication was intentionally not run.']
 ];
 get('figure-list').replaceChildren(...figures.map(([title,caption],i)=>{const a=node('article',undefined,'figure'),file=`self-study/figure-${i+1}`;a.append(node('h3',`${i+1}. ${title}`));const img=node('img');img.src=file+'.svg';img.alt=title+'. '+caption;img.loading='lazy';a.append(img,node('p',caption));const links=node('div',undefined,'downloads');for(const [label,ext,download] of [['Open full-size figure ↗','svg',false],['SVG','svg',true],['PDF','pdf',true],['PNG · 600 dpi','png',true]]){const l=node('a',label);l.href=file+'.'+ext;if(download)l.download=`figure-${i+1}.${ext}`;else{l.target='_blank';l.rel='noopener'}links.append(l)}a.append(links);return a}));
 let runs=[];
 const labels={attendance:'School attendance',health:'Community health',release:'After release'};
 function variants(){const candidates=runs.filter(r=>r.scenario===get('test-scenario').value&&r.kind===get('test-kind').value);get('test-variant').replaceChildren(...candidates.map(r=>{const o=node('option',r.variant+(r.kind==='minority'?` · assigned ${r.assigned_count}/32`:''));o.value=r.id;return o}));render();}
 function render(){const r=runs.find(r=>r.id===get('test-variant').value);if(!r)return;const box=get('test-record');box.replaceChildren(node('h3',labels[r.scenario]+' · '+r.variant));const meta=node('p',r.actual_words?`${r.actual_words} words · ${r.word_limit}-word cap · ${r.input.participants.length} input records`:'Prepared condition · authored assessment');box.append(meta);if(r.input.source_form_id){const link=node('a','Open source consultation ↗');link.href=`/admin/form/${r.input.source_form_id}/summary`;box.append(link)}box.append(node('h3','Saved output'),node('p',r.narrative,'opening'));if(r.decision)box.append(node('h3','Decision'),node('p',`${r.decision.action}. Regret: ${r.decision.regret} benchmark units. ${r.decision.reader}`));for(const [title,data] of [['Scoring record and evidence spans',r.audit],['Complete eligible input',r.input],['Calculated metrics',r.metrics||r.decision]]){const d=node('details'),s=node('summary',title),pre=node('pre',JSON.stringify(data,null,2));d.append(s,pre);box.append(d)}box.append(node('p',r.generation||'Authored in the same assistant conversation; not a separate model invocation.','small'));}
 Promise.all(['runs','summary'].map(async n=>{const r=await fetch(`self-study/${n}.json`);if(!r.ok)throw Error('Unavailable');return r.json()})).then(([r,s])=>{runs=r;get('self-summary').textContent=`${s.runs} prepared condition records · ${s.scenarios} authored scenarios · one assistant · zero OpenRouter calls.`;get('test-scenario').replaceChildren(...Object.entries(labels).map(([id,label])=>{const o=node('option',label);o.value=id;return o}));get('test-scenario').onchange=variants;get('test-kind').onchange=variants;get('test-variant').onchange=render;variants();}).catch(()=>{get('self-summary').textContent='Self-evaluation records could not be loaded. Please refresh.'});
})();
